<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>三人研发待办板</title>
<style>
  :root {
    --bg: #f4f6fb;
    --card: #ffffff;
    --ink: #1f2937;
    --muted: #6b7280;
    --line: #e5e7eb;
    --accent: #2563eb;
    --accent-ink: #ffffff;
    --done: #16a34a;
    --danger: #dc2626;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    padding: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    font-size: 16px;
    line-height: 1.5;
  }
  main {
    max-width: 640px;
    margin: 0 auto;
    padding: 32px 16px 48px;
  }
  .board {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  }
  h1 {
    font-size: 22px;
    margin: 0 0 4px;
  }
  .subtitle {
    margin: 0 0 16px;
    color: var(--muted);
    font-size: 13px;
  }
  .composer {
    display: flex;
    gap: 8px;
  }
  #task-input {
    flex: 1 1 auto;
    min-width: 0;
    padding: 10px 12px;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    font-size: 15px;
    background: #fff;
    color: var(--ink);
  }
  #task-input:focus {
    outline: 2px solid var(--accent);
    outline-offset: 1px;
    border-color: var(--accent);
  }
  button {
    font: inherit;
    cursor: pointer;
    border-radius: 8px;
    border: 1px solid transparent;
    padding: 10px 14px;
  }
  #add-btn {
    background: var(--accent);
    color: var(--accent-ink);
    white-space: nowrap;
  }
  #add-btn:hover { filter: brightness(0.95); }
  .stats {
    display: flex;
    gap: 16px;
    margin: 16px 0 8px;
    font-size: 14px;
    color: var(--muted);
  }
  .stats strong {
    color: var(--ink);
    font-weight: 600;
  }
  #todo-list {
    list-style: none;
    margin: 8px 0 0;
    padding: 0;
  }
  #todo-list li {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 4px;
    border-top: 1px solid var(--line);
  }
  #todo-list li:first-child { border-top: none; }
  .todo-text {
    flex: 1 1 auto;
    min-width: 0;
    word-break: break-word;
  }
  #todo-list li[data-completed="true"] .todo-text {
    color: var(--done);
    text-decoration: line-through;
  }
  .toggle-btn {
    background: #eef2ff;
    color: #3730a3;
    border-color: #dbe1ff;
    font-size: 13px;
    padding: 6px 10px;
    white-space: nowrap;
  }
  #todo-list li[data-completed="true"] .toggle-btn {
    background: #ecfdf5;
    color: #047857;
    border-color: #d1fae5;
  }
  .delete-btn {
    background: #fef2f2;
    color: var(--danger);
    border-color: #fee2e2;
    font-size: 13px;
    padding: 6px 10px;
    white-space: nowrap;
  }
  .empty {
    margin: 12px 0 0;
    color: var(--muted);
    font-size: 14px;
  }
  .empty[hidden] { display: none; }
</style>
</head>
<body>
<main>
  <section class="board" aria-label="三人研发待办板">
    <h1>三人研发待办板</h1>
    <p class="subtitle">离线单页 · 无需登录 · 刷新后重置</p>

    <form class="composer" id="composer" autocomplete="off">
      <input id="task-input" type="text" placeholder="输入任务后点击添加" aria-label="任务内容">
      <button id="add-btn" type="submit">添加</button>
    </form>

    <div class="stats" aria-live="polite">
      <span id="total-count">总数:0</span>
      <span id="done-count">已完成:0</span>
    </div>

    <ul id="todo-list"></ul>
    <p class="empty" id="empty-hint">暂无任务</p>
  </section>
</main>

<script>
(function () {
  "use strict";

  var MAX_TEXT_LENGTH = 200;

  /* 内存态数据源：无持久化，刷新即重置 */
  var tasks = [];

  var form = document.getElementById("composer");
  var input = document.getElementById("task-input");
  var listEl = document.getElementById("todo-list");
  var totalEl = document.getElementById("total-count");
  var doneEl = document.getElementById("done-count");
  var emptyHint = document.getElementById("empty-hint");

  function normalizeText(raw) {
    return String(raw == null ? "" : raw).replace(/\s+/g, " ").trim();
  }

  function render() {
    listEl.textContent = "";

    var total = tasks.length;
    var done = 0;

    for (var i = 0; i < tasks.length; i++) {
      var task = tasks[i];
      if (task.completed) { done++; }

      var li = document.createElement("li");
      li.setAttribute("data-completed", task.completed ? "true" : "false");
      li.setAttribute("data-index", String(i));

      var textSpan = document.createElement("span");
      textSpan.className = "todo-text";
      textSpan.textContent = task.completed ? (task.text + " \u2713") : task.text;

      var toggleBtn = document.createElement("button");
      toggleBtn.type = "button";
      toggleBtn.className = "toggle-btn";
      toggleBtn.textContent = task.completed ? "取消完成" : "完成";

      var deleteBtn = document.createElement("button");
      deleteBtn.type = "button";
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "删除";

      li.appendChild(textSpan);
      li.appendChild(toggleBtn);
      li.appendChild(deleteBtn);
      listEl.appendChild(li);
    }

    totalEl.textContent = "总数:" + total;
    doneEl.textContent = "已完成:" + done;
    emptyHint.hidden = total !== 0;
  }

  function addTask(rawText) {
    var text = normalizeText(rawText);
    if (text === "") { return false; }
    if (text.length > MAX_TEXT_LENGTH) {
      text = text.slice(0, MAX_TEXT_LENGTH);
    }
    tasks.push({ text: text, completed: false });
    render();
    return true;
  }

  function toggleTask(index) {
    if (index < 0 || index >= tasks.length) { return; }
    tasks[index].completed = !tasks[index].completed;
    render();
  }

  function deleteTask(index) {
    if (index < 0 || index >= tasks.length) { return; }
    tasks.splice(index, 1);
    render();
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    if (addTask(input.value)) {
      input.value = "";
    }
  });

  /* 事件委托：在列表容器上统一处理完成切换与删除 */
  listEl.addEventListener("click", function (event) {
    var target = event.target;
    if (!target || !target.closest) { return; }

    var li = target.closest("li");
    if (!li) { return; }

    var index = parseInt(li.getAttribute("data-index"), 10);
    if (isNaN(index)) { return; }

    if (target.closest(".toggle-btn")) {
      toggleTask(index);
    } else if (target.closest(".delete-btn")) {
      deleteTask(index);
    }
  });

  /* 初始状态 */
  input.value = "";
  render();
})();
</script>
</body>
</html>
