<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>三人研发待办板</title>
<style>
  :root {
    --bg: #f4f6fb;
    --card: #ffffff;
    --ink: #1f2937;
    --muted: #6b7280;
    --line: #e5e7eb;
    --accent: #2563eb;
    --accent-ink: #ffffff;
    --done: #16a34a;
    --danger: #dc2626;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    padding: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    font-size: 16px;
    line-height: 1.5;
  }
  main {
    max-width: 640px;
    margin: 0 auto;
    padding: 32px 16px 48px;
  }
  .board {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  }
  h1 {
    font-size: 22px;
    margin: 0 0 4px;
  }
  .subtitle {
    margin: 0 0 16px;
    color: var(--muted);
    font-size: 13px;
  }
  .composer {
    display: flex;
    gap: 8px;
  }
  #task-input {
    flex: 1 1 auto;
    min-width: 0;
    padding: 10px 12px;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    font-size: 15px;
    background: #fff;
    color: var(--ink);
  }
  #task-input:focus {
    outline: 2px solid var(--accent);
    outline-offset: 1px;
    border-color: var(--accent);
  }
  button {
    font: inherit;
    cursor: pointer;
    border-radius: 8px;
    border: 1px solid transparent;
    padding: 10px 14px;
  }
  #add-btn {
    background: var(--accent);
    color: var(--accent-ink);
    white-space: nowrap;
  }
  #add-btn:hover { filter: brightness(0.95); }
  .stats {
    display: flex;
    gap: 16px;
    margin: 16px 0 8px;
    font-size: 14px;
    color: var(--muted);
  }
  .stats strong {
    color: var(--ink);
    font-weight: 600;
  }
  #todo-list {
    list-style: none;
    margin: 8px 0 0;
    padding: 0;
  }
  #todo-list li {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 4px;
    border-top: 1px solid var(--line);
  }
  #todo-list li:first-child { border-top: none; }
  .todo-text {
    flex: 1 1 auto;
    min-width: 0;
    word-break: break-word;
  }
  #todo-list li[data-completed="true"] .todo-text {
    color: var(--done);
    text-decoration: line-through;
  }
  .toggle-btn {
    background: #eef2ff;
    color: #3730a3;
    border-color: #dbe1ff;
    font-size: 13px;
    padding: 6px 10px;
    white-space: nowrap;
  }
  #todo-list li[data-completed="true"] .toggle-btn {
    background: #ecfdf5;
    color: #047857;
    border-color: #d1fae5;
  }
  .delete-btn {
    background: #fef2f2;
    color: var(--danger);
    border-color: #fee2e2;
    font-size: 13px;
    padding: 6px 10px;
    white-space: nowrap;
  }
  .empty {
    margin: 12px 0 0;
    color: var(--muted);
    font-size: 14px;
  }
  .empty[hidden] { display: none; }
</style>
</head>
<body>
<main>
  <section class="board" aria-label="三人研发待办板">
    <h1>三人研发待办板</h1>
    <p class="subtitle">离线单页 · 无需登录 · 刷新后重置</p>

    <form class="composer" id="composer" autocomplete="off">
      <input id="task-input" type="text" placeholder="输入任务后点击添加" aria-label="任务内容">
      <button id="add-btn" type="submit">添加</button>
    </form>

    <div class="stats" aria-live="polite">
